import { Scene, Node } from '../src/aspose/threed';
import { ThreeMfLoadOptions, ThreeMfSaveOptions } from '../src/aspose/threed/formats/threemf';
import { Mesh } from '../src/aspose/threed/entities';
import { Vector4 } from '../src/aspose/threed/utilities';

describe('Test3MFRoundTrip', () => {
    it('testRoundTripExportImport', () => {
        const scene = new Scene();
        const loadOptions = new ThreeMfLoadOptions();
        const saveOptions = new ThreeMfSaveOptions();

        const mesh = new Mesh('test_cube');

        mesh.controlPoints.push(new Vector4(0, 0, 0, 1));
        mesh.controlPoints.push(new Vector4(1, 0, 0, 1));
        mesh.controlPoints.push(new Vector4(1, 1, 0, 1));
        mesh.controlPoints.push(new Vector4(0, 1, 0, 1));
        mesh.controlPoints.push(new Vector4(0, 0, 1, 1));
        mesh.controlPoints.push(new Vector4(1, 0, 1, 1));
        mesh.controlPoints.push(new Vector4(1, 1, 1, 1));
        mesh.controlPoints.push(new Vector4(0, 1, 1, 1));

        mesh.createPolygon(0, 1, 2);
        mesh.createPolygon(0, 2, 3);
        mesh.createPolygon(4, 7, 6);
        mesh.createPolygon(4, 6, 5);
        mesh.createPolygon(0, 4, 5);
        mesh.createPolygon(0, 5, 1);
        mesh.createPolygon(2, 6, 7);
        mesh.createPolygon(2, 7, 3);
        mesh.createPolygon(0, 3, 7);
        mesh.createPolygon(0, 7, 4);
        mesh.createPolygon(1, 5, 6);
        mesh.createPolygon(1, 6, 2);

        const node = new Node('test_cube');
        node.entity = mesh;
        node.parentNode = scene.rootNode;

        const originalVertices = mesh.controlPoints.length;
        const originalPolygons = mesh.polygonCount;

        scene.save('/tmp/test_roundtrip.3mf', saveOptions);

        const newScene = new Scene();
        newScene.open('/tmp/test_roundtrip.3mf', loadOptions);

        expect(newScene.rootNode.childNodes.length).toBeGreaterThan(0);

        const newMesh = newScene.rootNode.childNodes[0].entity as Mesh;
        expect(newMesh).toBeInstanceOf(Mesh);

        expect(newMesh!.controlPoints.length).toBe(originalVertices);
        expect(newMesh!.polygonCount).toBe(originalPolygons);
    });
});

import { Scene } from '../src/aspose/threed';
import { Mesh } from '../src/aspose/threed/entities';
import { Vector4, Vector3 } from '../src/aspose/threed/utilities';
import { ColladaSaveOptions, ColladaFormat } from '../src/aspose/threed/formats/collada';
import { PhongMaterial, LambertMaterial } from '../src/aspose/threed/shading';

describe('TestColladaExporter', () => {
    it('testSimpleTriangleExport', () => {
        const scene = new Scene();
        const mesh = new Mesh('TestMesh');

        mesh.controlPoints.push(new Vector4(0.0, 0.0, 0.0, 1.0));
        mesh.controlPoints.push(new Vector4(1.0, 0.0, 0.0, 1.0));
        mesh.controlPoints.push(new Vector4(0.0, 1.0, 0.0, 1.0));
        mesh.createPolygon(0, 1, 2);

        scene.rootNode.createChildNode('TestNode').entity = mesh;

        scene.save('/tmp/test_simple.dae', ColladaFormat.getInstance());
        expect(true).toBe(true);
    });

    it('testExportWithMaterial', () => {
        const scene = new Scene();
        const mesh = new Mesh('TestMesh');

        mesh.controlPoints.push(new Vector4(0.0, 0.0, 0.0, 1.0));
        mesh.controlPoints.push(new Vector4(1.0, 0.0, 0.0, 1.0));
        mesh.controlPoints.push(new Vector4(0.0, 1.0, 0.0, 1.0));
        mesh.createPolygon(0, 1, 2);

        const material = new PhongMaterial('RedMaterial');
        material.diffuseColor = new Vector3(1.0, 0.0, 0.0);
        material.specularColor = new Vector3(1.0, 1.0, 1.0);
        material.shininess = 32.0;

        const node = scene.rootNode.createChildNode('TestNode');
        node.entity = mesh;
        node.material = material;

        scene.save('/tmp/test_material.dae', ColladaFormat.getInstance());
        expect(true).toBe(true);
    });

    it('testExportLambertMaterial', () => {
        const scene = new Scene();
        const mesh = new Mesh('TestMesh');

        mesh.controlPoints.push(new Vector4(0.0, 0.0, 0.0, 1.0));
        mesh.controlPoints.push(new Vector4(1.0, 0.0, 0.0, 1.0));
        mesh.controlPoints.push(new Vector4(0.0, 1.0, 0.0, 1.0));
        mesh.createPolygon(0, 1, 2);

        const material = new LambertMaterial('BlueMaterial');
        material.diffuseColor = new Vector3(0.0, 0.0, 1.0);

        const node = scene.rootNode.createChildNode('TestNode');
        node.entity = mesh;
        node.material = material;

        scene.save('/tmp/test_lambert.dae', ColladaFormat.getInstance());
        expect(true).toBe(true);
    });

    it('testColladaSaveOptions', () => {
        const options = new ColladaSaveOptions();

        expect(options.flipCoordinateSystem).toBe(false);
        expect(options.enableMaterials).toBe(true);
        expect(options.indented).toBe(true);

        options.flipCoordinateSystem = true;
        expect(options.flipCoordinateSystem).toBe(true);

        options.indented = false;
        expect(options.indented).toBe(false);
    });

    it('testColladaFormatCanExport', () => {
        const colladaFormat = ColladaFormat;
        expect(colladaFormat.canExport).toBe(true);
    });
