      vertex 1.0 1.0 0.0
    endloop
  endfacet
  facet normal 0.0 0.0 -1.0
    outer loop
      vertex 0.0 0.0 0.0
      vertex 1.0 1.0 0.0
      vertex 0.0 1.0 0.0
    endloop
  endfacet
endsolid TestCube
`;
        const stream = new TextEncoder().encode(content);
        const options = new StlLoadOptions();

        scene.openFromBuffer(stream, options);

        expect(scene.rootNode).toBeDefined();
        expect(scene.rootNode.childNodes.length).toBe(1);

        const node = scene.rootNode.childNodes[0];
        expect(node.entity).toBeDefined();

        const mesh = node.entity as Mesh;
        expect(mesh.controlPoints.length).toBe(6);
        expect(mesh.polygonCount).toBe(2);
    });

    it('testStlFormat', () => {
        expect(StlFormat.canImport).toBe(true);
        expect(StlFormat.canExport).toBe(true);
        expect(StlFormat.extension).toBe("stl");
        expect(StlFormat.extensions).toContain("stl");
    });

    it('testLoadOptionsProperties', () => {
        const options = new StlLoadOptions();

        expect(options.flipCoordinateSystem).toBe(false);
        expect(options.scale).toBe(1.0);

        options.flipCoordinateSystem = true;
        options.scale = 2.5;

        expect(options.flipCoordinateSystem).toBe(true);
        expect(options.scale).toBe(2.5);
    });
});

import { Mesh } from '../src/aspose/threed';
import { PolygonModifier } from '../src/aspose/threed/entities';
import { Vector4 } from '../src/aspose/threed/utilities';

describe('testTriangulateConsistency', () => {
    it('testQuadMesh', () => {
        const quadMesh = new Mesh("quad");
        quadMesh.controlPoints = [
            new Vector4(0, 0, 0, 1),
            new Vector4(1, 0, 0, 1),
            new Vector4(0, 1, 0, 1),
            new Vector4(1, 1, 0, 1)
        ];
        quadMesh.createPolygon(0, 1, 3, 2);

        const result1 = quadMesh.triangulate();
        const result2 = PolygonModifier.triangulate(quadMesh);

        expect(result1.polygonCount).toBe(result2.polygonCount);
    });

    it('testMixedPolygonMesh', () => {
        const mixedMesh = new Mesh("mixed");
        mixedMesh.controlPoints = [
            new Vector4(0, 0, 0, 1),
            new Vector4(1, 0, 0, 1),
            new Vector4(0, 1, 0, 1),
            new Vector4(1, 1, 0, 1),
            new Vector4(2, 0, 0, 1),
            new Vector4(2, 1, 0, 1)
        ];
        mixedMesh.createPolygon(0, 1, 2);
        mixedMesh.createPolygon(1, 3, 2);
        mixedMesh.createPolygon([1, 3, 5, 4]);

        const result1 = mixedMesh.triangulate();
        const result2 = PolygonModifier.triangulate(mixedMesh);

        expect(result1.polygonCount).toBe(result2.polygonCount);
    });
});

